65	+using System.Net.Mail;
66	+using System.Security.Cryptography;
67	+using Microsoft.Data.SqlClient;
68	+using Microsoft.EntityFrameworkCore;
69	+using seed_a_backend.Api.Domain;
70	+using seed_a_backend.Api.Infrastructure;
71	+
72	+namespace seed_a_backend.Api.Application;
73	+
74	+/// <summary>
75	+/// Preisberechnung ausschließlich serverseitig aus PriceCategory (AD-3, NFR-6) — die Command-Form
76	+/// enthält bewusst kein Preisfeld, ein evtl. clientseitig berechneter Preis kann also strukturell
77	+/// nicht mitgesendet werden. Konflikterkennung über den Constraint-Namen aus der SqlException
78	+/// (AD-1): nur eine Verletzung des Sitzplatz-Unique-Index führt zu SEAT_CONFLICT, eine Reference-
79	+/// Kollision löst eine interne Neuerzeugung mit Retry aus, die der Besucher nie sieht.
80	+/// </summary>
81	+public class BookingService(AppDbContext db)
82	+{
83	+    private const string ReferenceAlphabet = "23456789ABCDEFGHJKMNPQRSTUVWXYZ"; // ohne 0/O/1/I/L (AD-4)
84	+    private const int ReferenceLength = 8;
85	+    private const int MaxReferenceAttempts = 5;
86	+
87	+    public async Task<BookingCreateResult> CreateBookingAsync(CreateBookingCommand command, CancellationToken ct = default)
88	+    {
89	+        var room = await (
90	+            from e in db.Events
91	+            join r in db.Rooms on e.RoomId equals r.Id
92	+            where e.Id == command.EventId
93	+            select r
94	+        ).SingleOrDefaultAsync(ct);
95	+
96	+        if (room is null)
97	+        {
98	+            return new BookingCreateResult.EventNotFound();
99	+        }
100	+
101	+        if (string.IsNullOrWhiteSpace(command.Name))
102	+        {
103	+            return new BookingCreateResult.ValidationFailed("Der Name darf nicht leer sein.");
104	+        }
105	+
106	+        if (!MailAddress.TryCreate(command.Email, out _))
107	+        {
108	+            return new BookingCreateResult.ValidationFailed("Die E-Mail-Adresse ist ungültig.");
109	+        }
110	+
111	+        if (command.Positions.Count == 0)
112	+        {
113	+            return new BookingCreateResult.ValidationFailed("Es muss mindestens ein Sitzplatz ausgewählt sein.");
114	+        }
115	+
116	+        if (command.Positions.GroupBy(p => (p.RowLabel, p.ColumnNumber)).Any(g => g.Count() > 1))
117	+        {
118	+            return new BookingCreateResult.ValidationFailed("Ein Sitzplatz ist mehrfach in der Auswahl enthalten.");
119	+        }
120	+
121	+        var priceCategories = await db.PriceCategories
122	+            .Where(pc => pc.EventId == command.EventId)
123	+            .ToDictionaryAsync(pc => pc.Id, ct);
124	+
125	+        foreach (var position in command.Positions)
126	+        {
127	+            var seatCode = SeatCode(position.RowLabel, position.ColumnNumber);
128	+
129	+            if (!room.RowLabels.Contains(position.RowLabel))
130	+            {
131	+                return new BookingCreateResult.ValidationFailed($"Sitzplatz '{seatCode}' existiert nicht in diesem Raum.");
132	+            }
133	+            if (position.ColumnNumber < 1 || position.ColumnNumber > room.ColumnCount)
134	+            {
135	+                return new BookingCreateResult.ValidationFailed($"Sitzplatz '{seatCode}' liegt außerhalb des Sitzplans.");
136	+            }
137	+            if (room.AisleColumns.Contains(position.ColumnNumber))
138	+            {
139	+                return new BookingCreateResult.ValidationFailed($"'{seatCode}' ist ein Gang, kein Sitzplatz.");
140	+            }
141	+            if (!priceCategories.ContainsKey(position.PriceCategoryId))
142	+            {
143	+                return new BookingCreateResult.ValidationFailed("Die gewählte Preiskategorie gehört nicht zu dieser Veranstaltung.");
144	+            }
145	+        }
146	+
147	+        // Deterministische Reihenfolge (RowLabel, dann ColumnNumber) zur Deadlock-Vermeidung bei
148	+        // gegenläufigen gleichzeitigen Insert-Reihenfolgen (AD-1).
149	+        var orderedPositions = command.Positions
150	+            .OrderBy(p => p.RowLabel, StringComparer.Ordinal)
151	+            .ThenBy(p => p.ColumnNumber)
152	+            .ToList();
153	+
154	+        var booking = new Booking
155	+        {
156	+            Reference = GenerateReference(),
157	+            Name = command.Name,
158	+            Email = command.Email,
159	+        };
160	+        foreach (var position in orderedPositions)
161	+        {
162	+            booking.Positions.Add(new BookingPosition
163	+            {
164	+                EventId = command.EventId,
165	+                RowLabel = position.RowLabel,
166	+                ColumnNumber = position.ColumnNumber,
167	+                PriceCategoryId = position.PriceCategoryId,
168	+            });
169	+        }
170	+
171	+        db.Bookings.Add(booking);
172	+
173	+        for (var attempt = 0; attempt < MaxReferenceAttempts; attempt++)
174	+        {
175	+            try
176	+            {
177	+                await db.SaveChangesAsync(ct);
178	+
179	+                var positionResults = orderedPositions
180	+                    .Select(p => new BookingPositionResult(p.RowLabel, p.ColumnNumber, ToSummary(priceCategories[p.PriceCategoryId])))
181	+                    .ToList();
182	+                var totalPrice = orderedPositions.Sum(p => priceCategories[p.PriceCategoryId].Preis);
183	+
184	+                return new BookingCreateResult.Success(new BookingResult(
185	+                    booking.Reference, booking.Name,
186	+                    booking.CancelledAtUtc is null ? "aktiv" : "storniert",
187	+                    positionResults, totalPrice));
188	+            }
189	+            catch (DbUpdateException ex) when (ex.InnerException is SqlException { Number: 2601 or 2627 } sql)
190	+            {
191	+                if (sql.Message.Contains(AppDbContext.BookingPositionSeatUniqueConstraintName))
192	+                {
193	+                    // Re-Read dient nur der Nutzer-Kommunikation, nicht der Korrektheitsprüfung
194	+                    // (die ist bereits durch den fehlgeschlagenen Insert entschieden, AD-1).
195	+                    var occupied = await db.BookingPositions
196	+                        .Where(bp => bp.EventId == command.EventId && bp.CancelledAtUtc == null)
197	+                        .Select(bp => new { bp.RowLabel, bp.ColumnNumber })
198	+                        .ToListAsync(ct);
199	+                    var occupiedSet = occupied.Select(o => (o.RowLabel, o.ColumnNumber)).ToHashSet();
200	+                    var conflicting = orderedPositions
201	+                        .Where(p => occupiedSet.Contains((p.RowLabel, p.ColumnNumber)))
202	+                        .Select(p => SeatCode(p.RowLabel, p.ColumnNumber))
203	+                        .ToList();
204	+                    return new BookingCreateResult.SeatConflict(conflicting);
205	+                }
206	+
207	+                if (sql.Message.Contains(AppDbContext.BookingReferenceUniqueConstraintName))
208	+                {
209	+                    booking.Reference = GenerateReference();
210	+                    continue;
211	+                }
212	+
213	+                throw;
214	+            }
215	+        }
216	+
217	+        throw new InvalidOperationException("Es konnte keine eindeutige Buchungsreferenz erzeugt werden.");
218	+    }
219	+
220	+    private static PriceCategorySummary ToSummary(PriceCategory pc) => new(pc.Id, pc.Name, pc.Preis);
221	+
222	+    /// <summary>Kombinierte Wire-/Anzeige-Form eines Sitzplatzes, z. B. "B3" (Consistency Convention).</summary>
223	+    private static string SeatCode(string rowLabel, int columnNumber) => $"{rowLabel}{columnNumber}";
224	+
225	+    private static string GenerateReference()
226	+    {
227	+        Span<char> chars = stackalloc char[ReferenceLength];
228	+        for (var i = 0; i < ReferenceLength; i++)
229	+        {
230	+            chars[i] = ReferenceAlphabet[RandomNumberGenerator.GetInt32(ReferenceAlphabet.Length)];
231	+        }
232	+        return new string(chars);
233	+    }
234	+}
