+    this.name().trim() !== '' &&
+    EMAIL_PATTERN.test(this.email()) &&
+    !this.submitting()
+  );
+
+  onSubmit(): void {
+    this.nameTouched.set(true);
+    this.emailTouched.set(true);
+    if (!this.canSubmit()) {
+      return;
+    }
+    this.submitted.emit({ name: this.name().trim(), email: this.email() });
+  }
+}
