+    status: 'aktiv',
+    positionen: [
+      { rowLabel: 'A', columnNumber: 1, preiskategorie: { id: 10, name: 'Kategorie A', preis: 32 } },
+      { rowLabel: 'A', columnNumber: 2, preiskategorie: { id: 20, name: 'Kategorie B', preis: 22 } }
