107	    /// EF-Core-Change-Tracking. Gemeinsame Konfiguration für `Room.RowLabels`/`Room.AisleColumns`,
108	    /// die sich zuvor nur im Element-/Property-Typ unterschied. `fromList` wrappt das deserialisierte
109	    /// `List&lt;TItem&gt;` in `TCollection` beim Aufrufer statt per ungesichertem `(TCollection)(object)`-Cast,
110	    /// der nur zufällig funktioniert, wenn `List&lt;TItem&gt;` tatsächlich in `TCollection` konvertierbar ist.
111	    /// </summary>
112	    private static void ConfigureJsonListConversion<TCollection, TItem>(
113	        PropertyBuilder<TCollection> property,
114	        Func<List<TItem>, TCollection> fromList)
115	        where TCollection : class, IReadOnlyCollection<TItem>
116	    {
117	        var empty = fromList(new List<TItem>());
118	
119	        property
120	            .HasConversion(
121	                v => JsonSerializer.Serialize(v, JsonSerializerOptions.Default),
122	                v => fromList(JsonSerializer.Deserialize<List<TItem>>(v, JsonSerializerOptions.Default) ?? new List<TItem>()))
123	            .Metadata.SetValueComparer(new ValueComparer<TCollection>(
124	                (a, b) => (a ?? empty).SequenceEqual(b ?? empty),
125	                v => (v ?? empty).Aggregate(0, (hash, item) => HashCode.Combine(hash, item)),
126	                v => fromList((v ?? empty).ToList())));
127	    }
