    // angefragten Sitzplätze melden, statt eine leere Liste zurückzugeben.
    conflicting = orderedPositions
        .Select(p => SeatCode(p.RowLabel, p.ColumnNumber))
        .ToList();
}
return new BookingCreateResult.SeatConflict(conflicting);

